49	const CursorIndicators = lazy(() => import("@/components/collaboration/cursor-indicators").then(m => ({ default: m.CursorIndicators })));
50	const ActivityFeed = lazy(() => import("@/components/collaboration/activity-feed").then(m => ({ default: m.ActivityFeed })));
51	const CommentsPanel = lazy(() => import("@/components/collaboration/comments-panel").then(m => ({ default: m.CommentsPanel })));
52	const VersionHistory = lazy(() => import("@/components/collaboration/version-history").then(m => ({ default: m.VersionHistory })));
53	const ShareDialog = lazy(() => import("@/components/collaboration/share-dialog").then(m => ({ default: m.ShareDialog })));
54	const NotificationBell = lazy(() => import("@/components/collaboration/notification-bell").then(m => ({ default: m.NotificationBell })));
