100	      { id: "balance",        label: "Balance",          icon: Scale,        statKey: null,             shortcut: null },
101	    ],
102	  },
103	  {
104	    label: "Playtesting",
105	    defaultOpen: false,
106	    items: [
107	      { id: "playtesting",    label: "Playtesting",      icon: Users,        statKey: "playtestCount",  shortcut: "7" },
108	      { id: "blind-playtest", label: "Blind Test",       icon: EyeOff,       statKey: null,             shortcut: null },
109	    ],
110	  },
111	  {
112	    label: "Publish",
113	    defaultOpen: false,
114	    items: [
115	      { id: "export",         label: "Exports",          icon: Download,     statKey: null,             shortcut: "8" },
116	    ],
117	  },
118	  {
119	    label: "Team",
120	    defaultOpen: true,
121	    items: [
122	      { id: "comments",       label: "Comments",         icon: MessageSquare,statKey: null,             shortcut: null },
123	      { id: "activity",       label: "Activity",         icon: History,      statKey: null,             shortcut: null },
124	      { id: "members",        label: "Members",          icon: Users,        statKey: null,             shortcut: null },
125	    ],
