133	export default function Workspace({ projectId: projectIdProp }: { projectId?: number } = {}) {
134	  const queryClient = useQueryClient();
135	  const params = useParams();
136	  const { user } = useUser();
137	  const { signOut } = useClerk();
138	  const projectId = useMemo(
139	    () => projectIdProp ?? parseInt(params.projectId || "0", 10),
140	    [projectIdProp, params.projectId],
141	  );
142	  const { data: project, isLoading: projectLoading } = useGetProject(projectId);
143	  const { data: stats } = useGetProjectStats(projectId);
144	  const deleteProject = useDeleteProject();
145	  const updateProject = useUpdateProject();
146	
147	  const [activeSection, setActiveSection] = useState<string>("overview");
148	  const [chatPrompt, setChatPrompt] = useState<string | undefined>();
149	  const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState(false);
150	  const [isShareDialogOpen, setIsShareDialogOpen] = useState(false);
151	  const [isRenameDialogOpen, setIsRenameDialogOpen] = useState(false);
152	  const [renameValue, setRenameValue] = useState("");
153	  const { showTour, startTour, completeTour, dismissTour } = useWorkspaceTour(projectId);
154	  const [openGroups, setOpenGroups] = useState<Record<string, boolean>>(() =>
155	    Object.fromEntries(NAV_GROUPS.map(g => [g.label, g.defaultOpen]))
156	  );
157	  const toggleGroup = (label: string) => setOpenGroups(g => ({ ...g, [label]: !g[label] }));
158	
159	  // Keyboard shortcuts
160	  useKeyboardShortcuts({
161	    quickActions: () => setChatPrompt(""),
162	    search: () => {
163	      // Focus on search if available, or show search UI
164	      const searchInput = document.querySelector('input[type="search"]') as HTMLInputElement;
165	      if (searchInput) searchInput.focus();
166	    },
167	    escape: () => {
168	      setIsDeleteDialogOpen(false);
169	      setIsShareDialogOpen(false);
170	      setIsRenameDialogOpen(false);
171	    },
172	    nav1: () => setActiveSection("overview"),
173	    nav2: () => setActiveSection("identity"),
174	    nav3: () => setActiveSection("research"),
175	    nav4: () => setActiveSection("players"),
176	    nav5: () => setActiveSection("assets-entities"),
177	    nav6: () => setActiveSection("rules"),
178	    nav7: () => setActiveSection("simulator"),
179	    nav8: () => setActiveSection("playtesting"),
180	    nav9: () => setActiveSection("playtesting"),
181	    quickCreateEntity: () => setActiveSection("assets-entities"),
182	    quickCreateRule: () => setActiveSection("rules"),
183	    quickCreateTask: () => setActiveSection("tasks"),
184	  });
185	
186	  if (projectLoading) {
187	    return <div className="h-screen w-full flex items-center justify-center bg-background text-foreground"><Skeleton className="h-32 w-64" /></div>;
188	  }
189	  if (!project) {
190	    return <div className="h-screen w-full flex items-center justify-center bg-background text-foreground">Project not found</div>;
191	  }
192	
193	  const handleDeleteProject = async () => {
194	    await deleteProject.mutateAsync({ projectId });
195	    queryClient.invalidateQueries({ queryKey: getListProjectsQueryKey() });
196	    window.location.href = import.meta.env.BASE_URL;
197	  };
198	
199	  const openRenameDialog = () => {
200	    setRenameValue(project?.name ?? "");
201	    setIsRenameDialogOpen(true);
202	  };
203	
204	  const handleRenameProject = (e: React.FormEvent) => {
205	    e.preventDefault();
206	    if (!renameValue.trim()) return;
207	    updateProject.mutate({ projectId, data: { name: renameValue.trim() } });
208	    setIsRenameDialogOpen(false);
209	  };
210	
211	  const getSectionCount = (key: string | null): number | null => {
212	    if (!key || !stats) return null;
213	    const v = (stats as unknown as Record<string, unknown>)[key];
214	    return typeof v === "number" ? v : null;
215	  };
216	
217	  const renderSection = () => {
218	    const loadingFallback = (
219	      <div className="flex items-center justify-center h-full">
220	        <Skeleton className="h-32 w-64" />
221	      </div>
222	    );
223	
224	    switch (activeSection) {
225	      case "overview": return (
226	        <ErrorBoundary>
227	          <Suspense fallback={loadingFallback}>
228	            <Overview projectId={projectId} onPromptSend={setChatPrompt} />
229	          </Suspense>
230	        </ErrorBoundary>
231	      );
232	      case "identity": return (
233	        <ErrorBoundary>
234	          <Suspense fallback={loadingFallback}>
235	            <GameIdentity projectId={projectId} onPromptSend={setChatPrompt} />
236	          </Suspense>
237	        </ErrorBoundary>
238	      );
239	      case "research": return (
240	        <ErrorBoundary>
241	          <Suspense fallback={loadingFallback}>
242	            <Research projectId={projectId} onPromptSend={setChatPrompt} workspaceSlug={params.workspaceSlug} />
243	          </Suspense>
244	        </ErrorBoundary>
245	      );
246	      case "assets-entities": return (
247	        <ErrorBoundary>
248	          <Suspense fallback={loadingFallback}>
249	            <AssetsEntities projectId={projectId} onChatPrompt={setChatPrompt} />
250	          </Suspense>
251	        </ErrorBoundary>
252	      );
253	      case "players": return (
254	        <ErrorBoundary>
255	          <Suspense fallback={loadingFallback}>
256	            <Players projectId={projectId} />
257	          </Suspense>
258	        </ErrorBoundary>
259	      );
260	      case "rules": return (
261	        <ErrorBoundary>
262	          <Suspense fallback={loadingFallback}>
263	            <Rules projectId={projectId} />
264	          </Suspense>
265	        </ErrorBoundary>
266	      );
267	      case "rulebook": return (
268	        <ErrorBoundary>
269	          <Suspense fallback={loadingFallback}>
270	            <RulebookEditor projectId={projectId} />
271	          </Suspense>
272	        </ErrorBoundary>
273	      );
274	      case "layout": return (
275	        <ErrorBoundary>
276	          <Suspense fallback={loadingFallback}>
277	            <LayoutEditor projectId={projectId} />
278	          </Suspense>
279	        </ErrorBoundary>
280	      );
281	      case "turn-structure": return (
282	        <ErrorBoundary>
283	          <Suspense fallback={loadingFallback}>
284	            <TurnStructure projectId={projectId} />
285	          </Suspense>
286	        </ErrorBoundary>
287	      );
288	      case "scaling": return (
289	        <ErrorBoundary>
290	          <Suspense fallback={loadingFallback}>
291	            <ScalingMatrix projectId={projectId} />
292	          </Suspense>
293	        </ErrorBoundary>
294	      );
295	      case "simulator": return (
296	        <ErrorBoundary>
297	          <Suspense fallback={loadingFallback}>
298	            <Simulator projectId={projectId} />
299	          </Suspense>
300	        </ErrorBoundary>
301	      );
302	      case "playtesting": return (
303	        <ErrorBoundary>
304	          <Suspense fallback={loadingFallback}>
305	            <Playtesting projectId={projectId} />
306	          </Suspense>
307	        </ErrorBoundary>
308	      );
309	      case "blind-playtest": return (
310	        <ErrorBoundary>
311	          <Suspense fallback={loadingFallback}>
312	            <BlindPlaytest projectId={projectId} />
313	          </Suspense>
314	        </ErrorBoundary>
315	      );
316	      case "playtest-reports": return (
317	        <ErrorBoundary>
318	          <Suspense fallback={loadingFallback}>
319	            <PlaytestReports projectId={projectId} />
320	          </Suspense>
321	        </ErrorBoundary>
322	      );
323	      case "notes": return (
324	        <ErrorBoundary>
325	          <Suspense fallback={loadingFallback}>
326	            <Notes projectId={projectId} />
327	          </Suspense>
328	        </ErrorBoundary>
329	      );
330	      case "tasks": return (
331	        <ErrorBoundary>
332	          <Suspense fallback={loadingFallback}>
333	            <Tasks projectId={projectId} />
334	          </Suspense>
335	        </ErrorBoundary>
336	      );
337	      case "scoring-curve": return (
338	        <ErrorBoundary>
339	          <Suspense fallback={loadingFallback}>
340	            <ScoringCurve projectId={projectId} />
341	          </Suspense>
342	        </ErrorBoundary>
343	      );
344	      case "balance": return (
345	        <ErrorBoundary>
346	          <Suspense fallback={loadingFallback}>
347	            <Balance projectId={projectId} />
348	          </Suspense>
349	        </ErrorBoundary>
350	      );
351	      case "export": return (
352	        <ErrorBoundary>
353	          <Suspense fallback={loadingFallback}>
354	            <Exports projectId={projectId} />
355	          </Suspense>
356	        </ErrorBoundary>
357	      );
358	      case "comments": return (
359	        <ErrorBoundary>
360	          <Suspense fallback={loadingFallback}>
361	            <CommentsPanel projectId={projectId} />
362	          </Suspense>
363	        </ErrorBoundary>
364	      );
365	      case "activity": return (
366	        <ErrorBoundary>
367	          <Suspense fallback={loadingFallback}>
368	            <ActivityFeed projectId={projectId} />
369	          </Suspense>
370	        </ErrorBoundary>
371	      );
372	      case "versions": return (
373	        <ErrorBoundary>
374	          <Suspense fallback={loadingFallback}>
375	            <VersionHistory projectId={projectId} />
376	          </Suspense>
377	        </ErrorBoundary>
378	      );
379	      case "members": return (
380	        <ErrorBoundary>
381	          <Suspense fallback={loadingFallback}>
382	            <MembersDirectory projectId={projectId} />
383	          </Suspense>
384	        </ErrorBoundary>
385	      );
386	      default: return null;
387	    }
388	  };
389	
390	  return (
391	    <div className="h-screen w-full flex bg-background text-foreground overflow-hidden">
392	      <div className="w-14 border-r border-border bg-sidebar flex flex-col items-center py-4 gap-3 shrink-0 z-10">
393	        <div className="bg-primary text-primary-foreground p-2 rounded-lg mb-2 shadow-lg">
394	          <Gamepad2 className="h-6 w-6" />
395	        </div>
396	
397	        <Tooltip>
398	          <TooltipTrigger asChild>
399	            <Link href="/" className="p-2.5 hover:bg-sidebar-accent rounded-md text-sidebar-foreground transition-colors group">
400	              <ChevronLeft className="h-5 w-5 group-hover:-translate-x-0.5 transition-transform" />
401	            </Link>
402	          </TooltipTrigger>
403	          <TooltipContent side="right">Back to projects</TooltipContent>
404	        </Tooltip>
405	
406	        <div className="mt-auto flex flex-col items-center gap-2 w-full pt-4 border-t border-border">
407	          <DropdownMenu>
408	            <DropdownMenuTrigger asChild>
409	              <button className="p-1.5 rounded-full hover:ring-2 hover:ring-primary/40 transition-all">
410	                {user?.imageUrl ? (
411	                  <img src={user.imageUrl} alt="" className="h-7 w-7 rounded-full" />
412	                ) : (
413	                  <div className="h-7 w-7 rounded-full bg-primary/20 flex items-center justify-center text-xs font-bold">{(user?.firstName?.[0] || user?.primaryEmailAddress?.emailAddress?.[0] || "U").toUpperCase()}</div>
414	                )}
415	              </button>
416	            </DropdownMenuTrigger>
417	            <DropdownMenuContent side="right" align="end">
418	              <DropdownMenuItem asChild><Link href="/account"><UserIcon className="h-4 w-4 mr-2" /> Account</Link></DropdownMenuItem>
419	              <DropdownMenuItem asChild>
420	                <Link
421	                  href="/learn"
422	                  data-testid="open-learn-from-workspace"
423	                  onClick={() => {
424	                    try { sessionStorage.setItem("gameforge.learn.returnTo", window.location.pathname + window.location.search); } catch {/* ignore */}
425	                  }}
426	                >
427	                  <GraduationCap className="h-4 w-4 mr-2" /> Learn
428	                </Link>
429	              </DropdownMenuItem>
430	              <DropdownMenuItem asChild><Link href="/admin"><Shield className="h-4 w-4 mr-2" /> Admin</Link></DropdownMenuItem>
431	              <DropdownMenuSeparator />
432	              <DropdownMenuItem onClick={() => signOut({ redirectUrl: "/" })}><LogOut className="h-4 w-4 mr-2" /> Sign out</DropdownMenuItem>
433	            </DropdownMenuContent>
434	          </DropdownMenu>
435	        </div>
436	      </div>
437	
438	      <div className="w-64 border-r border-border bg-sidebar flex flex-col shrink-0 z-10">
439	        <div className="p-5 border-b border-border">
440	          <div className="flex justify-between items-start mb-2">
441	            <h1 className="font-bold text-lg leading-tight line-clamp-2 pr-2">{project.name}</h1>
442	            <DropdownMenu>
443	              <DropdownMenuTrigger asChild>
444	                <Button variant="ghost" size="icon" className="h-6 w-6 shrink-0 -mr-2 text-muted-foreground hover:text-foreground">
445	                  <MoreVertical className="h-4 w-4" />
446	                </Button>
447	              </DropdownMenuTrigger>
448	              <DropdownMenuContent align="end">
449	                <DropdownMenuItem onClick={openRenameDialog}>
450	                  <Pencil className="h-4 w-4 mr-2" /> Rename
451	                </DropdownMenuItem>
452	                <DropdownMenuItem onClick={() => setIsShareDialogOpen(true)}>
453	                  <Share2 className="h-4 w-4 mr-2" /> Share
454	                </DropdownMenuItem>
455	                <DropdownMenuItem className="text-destructive focus:text-destructive cursor-pointer" onClick={() => setIsDeleteDialogOpen(true)}>
456	                  <Trash2 className="h-4 w-4 mr-2" /> Delete Project
457	                </DropdownMenuItem>
458	              </DropdownMenuContent>
459	            </DropdownMenu>
460	          </div>
461	          <div className="flex gap-1.5 flex-wrap text-xs text-muted-foreground">
462	            {project.gameType && <span className="px-2 py-0.5 bg-sidebar-accent rounded-full">{project.gameType}</span>}
463	            {project.genre && <span className="px-2 py-0.5 bg-sidebar-accent rounded-full">{project.genre}</span>}
464	            {project.playerCount && <span className="px-2 py-0.5 bg-sidebar-accent rounded-full">{project.playerCount}</span>}
465	          </div>
466	          <div className="mt-3 pt-3 border-t">
467	            <CollaborationPresence projectId={projectId} />
468	          </div>
469	        </div>
470	
471	        <nav className="flex-1 overflow-y-auto p-2 space-y-1">
472	          {NAV_GROUPS.map((group) => (
473	            <div key={group.label}>
474	              <button
475	                onClick={() => toggleGroup(group.label)}
476	                className="w-full flex items-center justify-between px-2 py-1.5 text-[10px] font-bold uppercase tracking-wider text-muted-foreground/60 hover:text-muted-foreground transition-colors"
477	              >
478	                {group.label}
479	                <ChevronRight className={`h-3 w-3 transition-transform ${openGroups[group.label] ? "rotate-90" : ""}`} />
480	              </button>
481	              {openGroups[group.label] && (
482	                <div className="space-y-0.5 mb-1">
483	                  {group.items.map((section) => {
484	                    const Icon = section.icon;
485	                    const statValue = section.statKey && stats ? (stats as any)[section.statKey] : null;
486	                    return (
487	                      <Tooltip key={section.id}>
488	                        <TooltipTrigger asChild>
489	                          <button
490	                            onClick={() => setActiveSection(section.id)}
491	                            className={`w-full flex items-center gap-2 px-3 py-2 rounded-lg text-sm transition-all ${
492	                              activeSection === section.id
493	                                ? "bg-sidebar-primary text-sidebar-primary-foreground font-medium"
494	                                : "text-sidebar-foreground hover:bg-sidebar-accent hover:text-sidebar-accent-foreground"
495	                            }`}
496	                          >
497	                            <Icon className="h-4 w-4 shrink-0" />
498	                            <span className="flex-1 text-left">{section.label}</span>
499	                            {statValue != null && <span className="text-xs opacity-60">{statValue}</span>}
500	                            {section.shortcut && <span className="text-xs opacity-40">{section.shortcut}</span>}
501	                          </button>
502	                        </TooltipTrigger>
503	                        <TooltipContent side="right">
504	                          <p>{section.label}{section.shortcut ? ` (Press ${section.shortcut})` : ""}</p>
505	                        </TooltipContent>
506	                      </Tooltip>
507	                    );
508	                  })}
509	                </div>
510	              )}
511	            </div>
512	          ))}
513	        </nav>
514	
515	        <div className="p-3 border-t border-border text-xs text-muted-foreground space-y-1">
516	          <TourTriggerButton onClick={startTour} />
517	          <div className="flex items-center gap-1 px-3 pt-1">
518	            <kbd className="px-1.5 py-0.5 bg-sidebar-accent rounded text-[10px] font-mono">⌘K</kbd>
519	            <span>Quick actions</span>
520	          </div>
521	          <div className="flex items-center gap-1 px-3">
522	            <kbd className="px-1.5 py-0.5 bg-sidebar-accent rounded text-[10px] font-mono">⌘/</kbd>
523	            <span>Search</span>
524	          </div>
525	        </div>
526	      </div>
527	
528	      <div className="flex-1 flex flex-col bg-background min-w-0">
529	        <div className="h-12 border-b border-border flex items-center px-6 bg-card text-muted-foreground gap-2 shrink-0 text-sm">
530	          <span className="font-medium text-foreground">{project.name}</span>
531	          <span>/</span>
532	          <span className="text-primary">{ALL_SECTION_LABELS[activeSection] ?? activeSection}</span>
533	          <div className="ml-auto flex items-center gap-2">
534	            <Suspense fallback={null}>
535	              <NotificationBell />
536	            </Suspense>
537	          </div>
538	        </div>
539	        <DesignBriefHeader project={project} />
540	        <div className="flex-1 p-6 overflow-y-auto">
541	          {renderSection()}
542	        </div>
543	      </div>
544	
545	      <ChatPanel projectId={projectId} defaultPrompt={chatPrompt} onPromptClear={() => setChatPrompt(undefined)} activeTab={activeSection} />
546	
547	      <AlertDialog open={isDeleteDialogOpen} onOpenChange={setIsDeleteDialogOpen}>
548	        <AlertDialogContent>
549	          <AlertDialogHeader>
550	            <AlertDialogTitle>Delete Project?</AlertDialogTitle>
551	            <AlertDialogDescription>
552	              Are you sure you want to delete "{project.name}"? This action cannot be undone.
553	            </AlertDialogDescription>
554	          </AlertDialogHeader>
555	          <AlertDialogFooter>
556	            <AlertDialogCancel>Cancel</AlertDialogCancel>
557	            <AlertDialogAction onClick={handleDeleteProject} className="bg-destructive text-destructive-foreground hover:bg-destructive/90">
558	              Delete
559	            </AlertDialogAction>
560	          </AlertDialogFooter>
561	        </AlertDialogContent>
562	      </AlertDialog>
563	
564	      <ShareDialog
565	        open={isShareDialogOpen}
566	        onOpenChange={setIsShareDialogOpen}
567	        projectId={projectId}
568	        projectName={project.name}
569	      />
570	
571	      <Dialog open={isRenameDialogOpen} onOpenChange={setIsRenameDialogOpen}>
572	        <DialogContent>
573	          <DialogHeader><DialogTitle>Rename project</DialogTitle></DialogHeader>
574	          <form onSubmit={handleRenameProject} className="space-y-4 py-2">
575	            <div className="space-y-1.5">
576	              <Label htmlFor="rename-project-name">Project name</Label>
577	              <Input
578	                id="rename-project-name"
579	                value={renameValue}
580	                onChange={(e) => setRenameValue(e.target.value)}
581	                autoFocus
582	              />
583	            </div>
584	            <DialogFooter>
585	              <Button type="button" variant="outline" onClick={() => setIsRenameDialogOpen(false)}>Cancel</Button>
586	              <Button type="submit" disabled={!renameValue.trim()}>Rename</Button>
587	            </DialogFooter>
588	          </form>
589	        </DialogContent>
590	      </Dialog>
591	
592	      <Suspense fallback={null}>
593	        <CursorIndicators projectId={projectId} />
594	      </Suspense>
595	
596	      <AnimatePresence>
597	        {showTour && (
598	          <WorkspaceTour
599	            onNavigate={(sectionId) => {
600	              setActiveSection(sectionId);
601	              const group = NAV_GROUPS.find(g => g.items.some(i => i.id === sectionId));
602	              if (group) setOpenGroups(prev => ({ ...prev, [group.label]: true }));
603	            }}
604	            onComplete={() => completeTour(projectId)}
605	            onDismiss={() => dismissTour(projectId)}
606	          />
607	        )}
608	      </AnimatePresence>
