  const activeStage = SECTION_TO_STAGE[activeSection] ?? 1;
  const activeStageConfig = STAGES[activeStage - 1];
  const activeChecklist = useMemo(
    () => project ? getStageChecklist(activeStage, project, stats) : [],
    [activeStage, project, stats],
